window.CARDS=[{"id": 1777118870718, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое бухгалтерский учёт?", "a": ["Процесс сбора, систематизированной записи и составления отчётности по финансово-экономической информации организации."], "frontHtml": "Что такое бухгалтерский учёт?", "backHtml": "\n\nПроцесс сбора, систематизированной записи и составления отчётности по финансово-экономической информации организации."}, {"id": 1777118870719, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три вида учёта в РФ", "a": ["Бухгалтерский, налоговый и управленческий учёт."], "frontHtml": "Три вида учёта в РФ", "backHtml": "\n\nБухгалтерский, налоговый и управленческий учёт."}, {"id": 1777118870720, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Для кого предназначен бухгалтерский учёт?", "a": ["Для внешних пользователей: инвесторов, банков, поставщиков, государственных органов."], "frontHtml": "Для кого предназначен бухгалтерский учёт?", "backHtml": "\n\nДля внешних пользователей: инвесторов, банков, поставщиков, государственных органов."}, {"id": 1777118870721, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Для кого предназначен управленческий учёт?", "a": ["Для внутренних пользователей: руководства и менеджеров организации."], "frontHtml": "Для кого предназначен управленческий учёт?", "backHtml": "\n\nДля внутренних пользователей: руководства и менеджеров организации."}, {"id": 1777118870722, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Для чего ведётся налоговый учёт в РФ?", "a": ["Только для расчёта налога на прибыль. Остальные налоги рассчитываются по данным бухучёта."], "frontHtml": "Для чего ведётся налоговый учёт в РФ?", "backHtml": "\n\nТолько для расчёта налога на прибыль. Остальные налоги рассчитываются по данным бухучёта."}, {"id": 1777118870723, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "На что ориентирован бухгалтерский учёт — на прошлое или будущее?", "a": ["На прошлое: отражает факты хозяйственной деятельности, которые уже произошли."], "frontHtml": "На что ориентирован бухгалтерский учёт — на прошлое или будущее?", "backHtml": "\n\nНа прошлое: отражает факты хозяйственной деятельности, которые уже произошли."}, {"id": 1777118870724, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "На что ориентирован управленческий учёт — на прошлое или будущее?", "a": ["На будущее: помогает планировать и принимать оперативные решения."], "frontHtml": "На что ориентирован управленческий учёт — на прошлое или будущее?", "backHtml": "\n\nНа будущее: помогает планировать и принимать оперативные решения."}, {"id": 1777118870725, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три основных отчёта бухгалтерского учёта", "a": ["1) Бухгалтерский баланс. 2) Отчёт о прибылях и убытках (ОПУ). 3) Отчёт о движении денежных средств (ОДДС)."], "frontHtml": "Три основных отчёта бухгалтерского учёта", "backHtml": "\n\n1) Бухгалтерский баланс. 2) Отчёт о прибылях и убытках (ОПУ). 3) Отчёт о движении денежных средств (ОДДС)."}, {"id": 1777118870726, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что показывает бухгалтерский баланс?", "a": ["Состав имущества (активов) и источники его финансирования (пассивов) на конкретную дату."], "frontHtml": "Что показывает бухгалтерский баланс?", "backHtml": "\n\nСостав имущества (активов) и источники его финансирования (пассивов) на конкретную дату."}, {"id": 1777118870727, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что показывает ОПУ?", "a": ["Доходы и расходы организации нарастающим итогом за определённый период"], "frontHtml": "Что показывает ОПУ?", "backHtml": "\n\nДоходы и расходы организации нарастающим итогом за определённый период"}, {"id": 1777118870728, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что показывает ОДДС?", "a": ["Фактические поступления и выплаты денежных средств за период."], "frontHtml": "Что показывает ОДДС?", "backHtml": "\n\nФактические поступления и выплаты денежных средств за период."}, {"id": 1777118870729, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Почему рост денег ≠ прибыль?", "a": ["В бухучёте расходы признаются по начислению (амортизация, списание страховки), а не только при оплате."], "frontHtml": "Почему рост денег ≠ прибыль?", "backHtml": "\n\nВ бухучёте расходы признаются по начислению (амортизация, списание страховки), а не только при оплате."}, {"id": 1777118870730, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Главное правило баланса", "a": ["Актив всегда равен пассиву."], "frontHtml": "Главное правило баланса", "backHtml": "\n\nАктив всегда равен пассиву."}, {"id": 1777118870731, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое постоянные расходы?", "a": ["Расходы, не зависящие от объёма деятельности: аренда, страховка, амортизация."], "frontHtml": "Что такое постоянные расходы?", "backHtml": "\n\nРасходы, не зависящие от объёма деятельности: аренда, страховка, амортизация."}, {"id": 1777118870732, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое переменные расходы?", "a": ["Расходы, растущие пропорционально объёму деятельности: сырьё, топливо, комиссии."], "frontHtml": "Что такое переменные расходы?", "backHtml": "\n\nРасходы, растущие пропорционально объёму деятельности: сырьё, топливо, комиссии."}, {"id": 1777118870733, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Формула точки безубыточности", "a": ["Постоянные расходы ÷ (Выручка на единицу − Переменные расходы на единицу)."], "frontHtml": "Формула точки безубыточности", "backHtml": "\n\nПостоянные расходы ÷ (Выручка на единицу − Переменные расходы на единицу)."}, {"id": 1777118870734, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПБУ — расшифровка и назначение", "a": ["Положение по бухгалтерскому учёту — нормативный документ 2-го уровня, регулирующий учёт отдельных объектов."], "frontHtml": "ПБУ — расшифровка и назначение", "backHtml": "\n\nПоложение по бухгалтерскому учёту — нормативный документ 2-го уровня, регулирующий учёт отдельных объектов."}, {"id": 1777118870735, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три уровня нормативного регулирования бухучёта", "a": ["1-й: ФЗ и приказы Минфина. 2-й: ПБУ. 3-й: Методические указания и учётная политика организации."], "frontHtml": "Три уровня нормативного регулирования бухучёта", "backHtml": "\n\n1-й: ФЗ и приказы Минфина. 2-й: ПБУ. 3-й: Методические указания и учётная политика организации."}, {"id": 1777118870736, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое уставный капитал?", "a": ["Первоначальная доля собственников в активах фирмы, равная сумме вкладов учредителей при создании."], "frontHtml": "Что такое уставный капитал?", "backHtml": "\n\nПервоначальная доля собственников в активах фирмы, равная сумме вкладов учредителей при создании."}, {"id": 1777118870737, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что происходит с имуществом учредителя после вклада в уставный капитал?", "a": ["Имущество переходит в собственность фирмы"], "frontHtml": "Что происходит с имуществом учредителя после вклада в уставный капитал?", "backHtml": "\n\nИмущество переходит в собственность фирмы"}, {"id": 1777118870738, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Чем кредит отличается от займа?", "a": ["Кредит — деньги от банка. Заём — деньги от других организаций или физических лиц."], "frontHtml": "Чем кредит отличается от займа?", "backHtml": "\n\nКредит — деньги от банка. Заём — деньги от других организаций или физических лиц."}, {"id": 1777118870739, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три признака заёмных средств", "a": ["Срочность (на определённый срок), платность (проценты), возвратность (независимо от прибыли)."], "frontHtml": "Три признака заёмных средств", "backHtml": "\n\nСрочность (на определённый срок), платность (проценты), возвратность (независимо от прибыли)."}, {"id": 1777118870740, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое кредиторская задолженность?", "a": ["Долг фирмы перед другими лицами за уже полученные, но ещё не оплаченные товары, работы или услуги."], "frontHtml": "Что такое кредиторская задолженность?", "backHtml": "\n\nДолг фирмы перед другими лицами за уже полученные, но ещё не оплаченные товары, работы или услуги."}, {"id": 1777118870741, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Чем кредиторская задолженность отличается от банковского кредита?", "a": ["КЗ обычно не имеет чётких сроков и процентов. Кредит — строго срочный и платный."], "frontHtml": "Чем кредиторская задолженность отличается от банковского кредита?", "backHtml": "\n\nКЗ обычно не имеет чётких сроков и процентов. Кредит — строго срочный и платный."}, {"id": 1777118870742, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Два вида активов по сроку использования", "a": ["Внеоборотные (> 1 года) и оборотные (≤ 1 года или постоянно в обороте)."], "frontHtml": "Два вида активов по сроку использования", "backHtml": "\n\nВнеоборотные (&gt; 1 года) и оборотные (≤ 1 года или постоянно в обороте)."}, {"id": 1777118870743, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Примеры внеоборотных активов", "a": ["НМА, основные средства, незавершённое строительство, долгосрочные финансовые вложения."], "frontHtml": "Примеры внеоборотных активов", "backHtml": "\n\nНМА, основные средства, незавершённое строительство, долгосрочные финансовые вложения."}, {"id": 1777118870744, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Примеры оборотных активов", "a": ["Материалы, незавершённое производство, готовая продукция, деньги, дебиторская задолженность."], "frontHtml": "Примеры оборотных активов", "backHtml": "\n\nМатериалы, незавершённое производство, готовая продукция, деньги, дебиторская задолженность."}, {"id": 1777118870745, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "По какой стоимости активы отражаются в балансе?", "a": ["По первоначальной (исторической) стоимости — стоимости приобретения или создания."], "frontHtml": "По какой стоимости активы отражаются в балансе?", "backHtml": "\n\nПо первоначальной (исторической) стоимости — стоимости приобретения или создания."}, {"id": 1777118870746, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НМА — расшифровка и определение", "a": ["Нематериальные активы — активы без материальной формы, используемые > 12 месяцев и приносящие экономическую выгоду."], "frontHtml": "НМА — расшифровка и определение", "backHtml": "\n\nНематериальные активы — активы без материальной формы, используемые &gt; 12 месяцев и приносящие экономическую выгоду."}, {"id": 1777118870747, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Шесть условий признания актива нематериальным", "a": ["1. Нет материальной формы. 2. Отделим. 3. Используется в производстве. 4. Срок > 12 мес. 5. Не для перепродажи. 6. Подтверждён документами."], "frontHtml": "Шесть условий признания актива нематериальным", "backHtml": "\n\n1. Нет материальной формы. 2. Отделим. 3. Используется в производстве. 4. Срок &gt; 12 мес. 5. Не для перепродажи. 6. Подтверждён документами."}, {"id": 1777118870748, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое деловая репутация (гудвилл)?", "a": ["Разница между ценой покупки бизнеса как имущественного комплекса и стоимостью его чистых активов."], "frontHtml": "Что такое деловая репутация (гудвилл)?", "backHtml": "\n\nРазница между ценой покупки бизнеса как имущественного комплекса и стоимостью его чистых активов."}, {"id": 1777118870749, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как амортизируется деловая репутация?", "a": ["Только линейным методом в течение 20 лет."], "frontHtml": "Как амортизируется деловая репутация?", "backHtml": "\n\nТолько линейным методом в течение 20 лет."}, {"id": 1777118870750, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "По какой стоимости НМА отражаются в балансе?", "a": ["По остаточной стоимости = первоначальная стоимость − накопленная амортизация."], "frontHtml": "По какой стоимости НМА отражаются в балансе?", "backHtml": "\n\nПо остаточной стоимости = первоначальная стоимость − накопленная амортизация."}, {"id": 1777118870751, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что входит в первоначальную стоимость НМА при покупке?", "a": ["Цена продавца (без НДС), невозмещаемые налоги, расходы на доработку, пошлины, услуги нотариуса и консультантов."], "frontHtml": "Что входит в первоначальную стоимость НМА при покупке?", "backHtml": "\n\nЦена продавца (без НДС), невозмещаемые налоги, расходы на доработку, пошлины, услуги нотариуса и консультантов."}, {"id": 1777118870752, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ОС — расшифровка и определение", "a": ["Основные средства — материальное имущество, используемое в производстве или управлении более 1 года."], "frontHtml": "ОС — расшифровка и определение", "backHtml": "\n\nОсновные средства — материальное имущество, используемое в производстве или управлении более 1 года."}, {"id": 1777118870753, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Нормативный документ, регулирующий учёт ОС", "a": ["ПБУ 6/01 «Учёт основных средств»."], "frontHtml": "Нормативный документ, регулирующий учёт ОС", "backHtml": "\n\nПБУ 6/01 «Учёт основных средств»."}, {"id": 1777118870754, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "При каком условии ОС стоимостью менее 40 000 руб. можно не ставить на учёт как ОС?", "a": ["Разрешено учитывать как запасы и списывать в расходы при вводе в эксплуатацию."], "frontHtml": "При каком условии ОС стоимостью менее 40 000 руб. можно не ставить на учёт как ОС?", "backHtml": "\n\nРазрешено учитывать как запасы и списывать в расходы при вводе в эксплуатацию."}, {"id": 1777118870755, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое инвентарный объект?", "a": ["Единица учёта ОС — отдельный предмет или комплекс предметов на общем фундаменте с единым управлением."], "frontHtml": "Что такое инвентарный объект?", "backHtml": "\n\nЕдиница учёта ОС — отдельный предмет или комплекс предметов на общем фундаменте с единым управлением."}, {"id": 1777118870756, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "По какой стоимости ОС отражаются в балансе?", "a": ["По остаточной стоимости = первоначальная стоимость − накопленная амортизация."], "frontHtml": "По какой стоимости ОС отражаются в балансе?", "backHtml": "\n\nПо остаточной стоимости = первоначальная стоимость − накопленная амортизация."}, {"id": 1777118870757, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое амортизация?", "a": ["Постепенное перенесение стоимости ОС или НМА на затраты в течение срока полезного использования."], "frontHtml": "Что такое амортизация?", "backHtml": "\n\nПостепенное перенесение стоимости ОС или НМА на затраты в течение срока полезного использования."}, {"id": 1777118870758, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Формула годовой амортизации при линейном методе", "a": ["Первоначальная стоимость ÷ Срок полезного использования (в годах)."], "frontHtml": "Формула годовой амортизации при линейном методе", "backHtml": "\n\nПервоначальная стоимость ÷ Срок полезного использования (в годах)."}, {"id": 1777118870759, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Какие ОС не амортизируются?", "a": ["Земля, природные ресурсы, объекты на консервации > 3 мес., объекты на реконструкции > 12 мес."], "frontHtml": "Какие ОС не амортизируются?", "backHtml": "\n\nЗемля, природные ресурсы, объекты на консервации &gt; 3 мес., объекты на реконструкции &gt; 12 мес."}, {"id": 1777118870760, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Четыре метода начисления амортизации ОС", "a": ["1. Линейный. 2. Уменьшаемого остатка. 3. По сумме чисел лет. 4. Пропорционально объёму продукции."], "frontHtml": "Четыре метода начисления амортизации ОС", "backHtml": "\n\n1. Линейный. 2. Уменьшаемого остатка. 3. По сумме чисел лет. 4. Пропорционально объёму продукции."}, {"id": 1777118870761, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Когда можно изменить первоначальную стоимость ОС?", "a": ["При достройке, дооборудовании, реконструкции/модернизации, частичной ликвидации или переоценке."], "frontHtml": "Когда можно изменить первоначальную стоимость ОС?", "backHtml": "\n\nПри достройке, дооборудовании, реконструкции/модернизации, частичной ликвидации или переоценке."}, {"id": 1777118870762, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Влияет ли ремонт на стоимость ОС?", "a": ["Нет. Ремонт — текущий расход"], "frontHtml": "Влияет ли ремонт на стоимость ОС?", "backHtml": "\n\nНет. Ремонт — текущий расход"}, {"id": 1777118870763, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как часто можно проводить переоценку ОС?", "a": ["Не чаще одного раза в год (на конец года), по группам однородных ОС."], "frontHtml": "Как часто можно проводить переоценку ОС?", "backHtml": "\n\nНе чаще одного раза в год (на конец года), по группам однородных ОС."}, {"id": 1777118870764, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что происходит при дооценке ОС?", "a": ["Увеличивается добавочный капитал в пассиве баланса."], "frontHtml": "Что происходит при дооценке ОС?", "backHtml": "\n\nУвеличивается добавочный капитал в пассиве баланса."}, {"id": 1777118870765, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НДС — расшифровка", "a": ["Налог на добавленную стоимость."], "frontHtml": "НДС — расшифровка", "backHtml": "\n\nНалог на добавленную стоимость."}, {"id": 1777118870766, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НК РФ — расшифровка", "a": ["Налоговый кодекс Российской Федерации."], "frontHtml": "НК РФ — расшифровка", "backHtml": "\n\nНалоговый кодекс Российской Федерации."}, {"id": 1777118870767, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НИОКР — расшифровка", "a": ["Научно-исследовательские и опытно-конструкторские работы."], "frontHtml": "НИОКР — расшифровка", "backHtml": "\n\nНаучно-исследовательские и опытно-конструкторские работы."}, {"id": 1777118870768, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НИР — расшифровка", "a": ["Научно-исследовательские работы."], "frontHtml": "НИР — расшифровка", "backHtml": "\n\nНаучно-исследовательские работы."}, {"id": 1777118870769, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ОПУ — расшифровка", "a": ["Отчёт о прибылях и убытках."], "frontHtml": "ОПУ — расшифровка", "backHtml": "\n\nОтчёт о прибылях и убытках."}, {"id": 1777118870770, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ОДДС — расшифровка", "a": ["Отчёт о движении денежных средств."], "frontHtml": "ОДДС — расшифровка", "backHtml": "\n\nОтчёт о движении денежных средств."}, {"id": 1777118870771, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "УК — расшифровка", "a": ["Уставный капитал."], "frontHtml": "УК — расшифровка", "backHtml": "\n\nУставный капитал."}, {"id": 1777118870772, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "КЗ — расшифровка", "a": ["Кредиторская задолженность."], "frontHtml": "КЗ — расшифровка", "backHtml": "\n\nКредиторская задолженность."}, {"id": 1777118870773, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ДЗ — расшифровка", "a": ["Дебиторская задолженность."], "frontHtml": "ДЗ — расшифровка", "backHtml": "\n\nДебиторская задолженность."}, {"id": 1777118870774, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ОС — расшифровка (аббревиатура)", "a": ["Основные средства."], "frontHtml": "ОС — расшифровка (аббревиатура)", "backHtml": "\n\nОсновные средства."}, {"id": 1777118870775, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НМА — расшифровка (аббревиатура)", "a": ["Нематериальные активы."], "frontHtml": "НМА — расшифровка (аббревиатура)", "backHtml": "\n\nНематериальные активы."}, {"id": 1777118870776, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПБУ 6/01 — что регулирует?", "a": ["Учёт основных средств."], "frontHtml": "ПБУ 6/01 — что регулирует?", "backHtml": "\n\nУчёт основных средств."}, {"id": 1777118870777, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПБУ 14/2007 — что регулирует?", "a": ["Учёт нематериальных активов."], "frontHtml": "ПБУ 14/2007 — что регулирует?", "backHtml": "\n\nУчёт нематериальных активов."}, {"id": 1777129948327, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое бухгалтерский учёт?", "a": ["Процесс сбора, систематизированной записи и составления отчётности по финансово-экономической информации организации."], "frontHtml": "Что такое бухгалтерский учёт?", "backHtml": "\n\nПроцесс сбора, систематизированной записи и составления отчётности по финансово-экономической информации организации."}, {"id": 1777129948328, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Четыре компонента системы учёта", "a": ["1. Сбор информации. 2. Запись. 3. Анализ и интерпретация. 4. Составление отчётности."], "frontHtml": "Четыре компонента системы учёта", "backHtml": "\n\n1. Сбор информации. 2. Запись. 3. Анализ и интерпретация. 4. Составление отчётности."}, {"id": 1777129948329, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Какие компоненты охватывает бухгалтерский учёт?", "a": ["Компоненты 1, 2 и 4: сбор, запись и отчётность. Управленческий учёт — компонент 3 (анализ)."], "frontHtml": "Какие компоненты охватывает бухгалтерский учёт?", "backHtml": "\n\nКомпоненты 1, 2 и 4: сбор, запись и отчётность. Управленческий учёт — компонент 3 (анализ)."}, {"id": 1777129948330, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три вида учёта в РФ", "a": ["Бухгалтерский, налоговый и управленческий учёт."], "frontHtml": "Три вида учёта в РФ", "backHtml": "\n\nБухгалтерский, налоговый и управленческий учёт."}, {"id": 1777129948331, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Для кого предназначен бухгалтерский учёт?", "a": ["Для внешних пользователей: инвесторов, банков, поставщиков, государственных органов."], "frontHtml": "Для кого предназначен бухгалтерский учёт?", "backHtml": "\n\nДля внешних пользователей: инвесторов, банков, поставщиков, государственных органов."}, {"id": 1777129948332, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Для кого предназначен управленческий учёт?", "a": ["Для внутренних пользователей: руководства и менеджеров организации."], "frontHtml": "Для кого предназначен управленческий учёт?", "backHtml": "\n\nДля внутренних пользователей: руководства и менеджеров организации."}, {"id": 1777129948333, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Для чего ведётся налоговый учёт в РФ?", "a": ["Только для расчёта налога на прибыль. Остальные налоги считаются по данным бухучёта."], "frontHtml": "Для чего ведётся налоговый учёт в РФ?", "backHtml": "\n\nТолько для расчёта налога на прибыль. Остальные налоги считаются по данным бухучёта."}, {"id": 1777129948334, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "На что ориентирован бухгалтерский учёт — на прошлое или будущее?", "a": ["На прошлое: отражает уже произошедшие хозяйственные факты."], "frontHtml": "На что ориентирован бухгалтерский учёт — на прошлое или будущее?", "backHtml": "\n\nНа прошлое: отражает уже произошедшие хозяйственные факты."}, {"id": 1777129948335, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "На что ориентирован управленческий учёт — на прошлое или будущее?", "a": ["На будущее: помогает планировать и принимать оперативные решения."], "frontHtml": "На что ориентирован управленческий учёт — на прошлое или будущее?", "backHtml": "\n\nНа будущее: помогает планировать и принимать оперативные решения."}, {"id": 1777129948336, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три основных отчёта бухгалтерского учёта", "a": ["1. Бухгалтерский баланс. 2. ОПУ (Отчёт о прибылях и убытках). 3. ОДДС (Отчёт о движении денежных средств)."], "frontHtml": "Три основных отчёта бухгалтерского учёта", "backHtml": "\n\n1. Бухгалтерский баланс. 2. ОПУ (Отчёт о прибылях и убытках). 3. ОДДС (Отчёт о движении денежных средств)."}, {"id": 1777129948337, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что показывает бухгалтерский баланс?", "a": ["Состав имущества (активов) и источники его финансирования (пассивов) на конкретную дату."], "frontHtml": "Что показывает бухгалтерский баланс?", "backHtml": "\n\nСостав имущества (активов) и источники его финансирования (пассивов) на конкретную дату."}, {"id": 1777129948338, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что показывает ОПУ?", "a": ["Доходы и расходы нарастающим итогом за период. Итог — прибыль или убыток."], "frontHtml": "Что показывает ОПУ?", "backHtml": "\n\nДоходы и расходы нарастающим итогом за период. Итог — прибыль или убыток."}, {"id": 1777129948339, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что показывает ОДДС?", "a": ["Реальные поступления и выплаты денежных средств за период."], "frontHtml": "Что показывает ОДДС?", "backHtml": "\n\nРеальные поступления и выплаты денежных средств за период."}, {"id": 1777129948340, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Главное правило баланса", "a": ["Актив всегда равен пассиву."], "frontHtml": "Главное правило баланса", "backHtml": "\n\nАктив всегда равен пассиву."}, {"id": 1777129948341, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Почему рост денег ≠ прибыль?", "a": ["Бухучёт признаёт расходы по начислению (амортизация, страховка), а не только при оплате. Деньги могут расти, а прибыль быть отрицательной."], "frontHtml": "Почему рост денег ≠ прибыль?", "backHtml": "\n\nБухучёт признаёт расходы по начислению (амортизация, страховка), а не только при оплате. Деньги могут расти, а прибыль быть отрицательной."}, {"id": 1777129948342, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое постоянные расходы?", "a": ["Расходы, не зависящие от объёма деятельности: аренда, страховка, амортизация."], "frontHtml": "Что такое постоянные расходы?", "backHtml": "\n\nРасходы, не зависящие от объёма деятельности: аренда, страховка, амортизация."}, {"id": 1777129948343, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое переменные расходы?", "a": ["Расходы, растущие пропорционально объёму деятельности: сырьё, топливо, комиссии."], "frontHtml": "Что такое переменные расходы?", "backHtml": "\n\nРасходы, растущие пропорционально объёму деятельности: сырьё, топливо, комиссии."}, {"id": 1777129948344, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Формула точки безубыточности", "a": ["Постоянные расходы ÷ (Выручка на единицу − Переменные расходы на единицу)."], "frontHtml": "Формула точки безубыточности", "backHtml": "\n\nПостоянные расходы ÷ (Выручка на единицу − Переменные расходы на единицу)."}, {"id": 1777129948345, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое условно-постоянные расходы?", "a": ["Расходы, в основном постоянные, но частично зависящие от объёма деятельности (например, ремонт автомобиля)."], "frontHtml": "Что такое условно-постоянные расходы?", "backHtml": "\n\nРасходы, в основном постоянные, но частично зависящие от объёма деятельности (например, ремонт автомобиля)."}, {"id": 1777129948346, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три уровня нормативного регулирования бухучёта", "a": ["1-й: ФЗ и приказы Минфина. 2-й: ПБУ. 3-й: Методические указания и учётная политика организации."], "frontHtml": "Три уровня нормативного регулирования бухучёта", "backHtml": "\n\n1-й: ФЗ и приказы Минфина. 2-й: ПБУ. 3-й: Методические указания и учётная политика организации."}, {"id": 1777129948347, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПБУ — расшифровка и назначение", "a": ["Положение по бухгалтерскому учёту — нормативный документ 2-го уровня, регулирующий учёт отдельных объектов."], "frontHtml": "ПБУ — расшифровка и назначение", "backHtml": "\n\nПоложение по бухгалтерскому учёту — нормативный документ 2-го уровня, регулирующий учёт отдельных объектов."}, {"id": 1777129948348, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Нормативная база налогового учёта", "a": ["НК РФ (Налоговый кодекс Российской Федерации), прежде всего глава 25 «Налог на прибыль»."], "frontHtml": "Нормативная база налогового учёта", "backHtml": "\n\nНК РФ (Налоговый кодекс Российской Федерации), прежде всего глава 25 «Налог на прибыль»."}, {"id": 1777129948349, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое уставный капитал?", "a": ["Первоначальная доля собственников в активах фирмы, равная сумме вкладов учредителей при создании."], "frontHtml": "Что такое уставный капитал?", "backHtml": "\n\nПервоначальная доля собственников в активах фирмы, равная сумме вкладов учредителей при создании."}, {"id": 1777129948350, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что происходит с имуществом учредителя после вклада в УК?", "a": ["Имущество переходит в собственность фирмы. Учредитель владеет только долями или акциями."], "frontHtml": "Что происходит с имуществом учредителя после вклада в УК?", "backHtml": "\n\nИмущество переходит в собственность фирмы. Учредитель владеет только долями или акциями."}, {"id": 1777129948351, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "В каких формах может быть сделан вклад в УК?", "a": ["Деньги, основные средства, НМА, ценные бумаги, имущественные права."], "frontHtml": "В каких формах может быть сделан вклад в УК?", "backHtml": "\n\nДеньги, основные средства, НМА, ценные бумаги, имущественные права."}, {"id": 1777129948352, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Минимальный УК для ООО и ОАО", "a": ["ООО — 10 000 руб. ОАО — 100 000 руб."], "frontHtml": "Минимальный УК для ООО и ОАО", "backHtml": "\n\nООО — 10 000 руб. ОАО — 100 000 руб."}, {"id": 1777129948353, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое добавочный капитал?", "a": ["Капитал, сформированный за счёт эмиссионного дохода (продажа акций выше номинала) и дооценки ОС и НМА."], "frontHtml": "Что такое добавочный капитал?", "backHtml": "\n\nКапитал, сформированный за счёт эмиссионного дохода (продажа акций выше номинала) и дооценки ОС и НМА."}, {"id": 1777129948354, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое нераспределённая прибыль?", "a": ["Накопленная прибыль после уплаты налогов, не выплаченная акционерам в виде дивидендов."], "frontHtml": "Что такое нераспределённая прибыль?", "backHtml": "\n\nНакопленная прибыль после уплаты налогов, не выплаченная акционерам в виде дивидендов."}, {"id": 1777129948355, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое непокрытый убыток?", "a": ["Накопленный убыток фирмы, отражаемый в пассиве со знаком минус. Уменьшает капитал собственников."], "frontHtml": "Что такое непокрытый убыток?", "backHtml": "\n\nНакопленный убыток фирмы, отражаемый в пассиве со знаком минус. Уменьшает капитал собственников."}, {"id": 1777129948356, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое резервный капитал?", "a": ["Часть прибыли, зарезервированная по решению акционеров для покрытия убытков и выплаты дивидендов в убыточные годы."], "frontHtml": "Что такое резервный капитал?", "backHtml": "\n\nЧасть прибыли, зарезервированная по решению акционеров для покрытия убытков и выплаты дивидендов в убыточные годы."}, {"id": 1777129948357, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Чем кредит отличается от займа?", "a": ["Кредит — деньги от банка. Заём — деньги от других организаций или физических лиц."], "frontHtml": "Чем кредит отличается от займа?", "backHtml": "\n\nКредит — деньги от банка. Заём — деньги от других организаций или физических лиц."}, {"id": 1777129948358, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три признака заёмных средств", "a": ["Срочность (на определённый срок), платность (проценты), возвратность (независимо от прибыли)."], "frontHtml": "Три признака заёмных средств", "backHtml": "\n\nСрочность (на определённый срок), платность (проценты), возвратность (независимо от прибыли)."}, {"id": 1777129948359, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как отражаются займы и кредиты в балансе?", "a": ["По сумме основного долга плюс начисленные проценты."], "frontHtml": "Как отражаются займы и кредиты в балансе?", "backHtml": "\n\nПо сумме основного долга плюс начисленные проценты."}, {"id": 1777129948360, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое кредиторская задолженность?", "a": ["Долги фирмы перед другими лицами за уже полученные, но ещё не оплаченные товары, работы или услуги."], "frontHtml": "Что такое кредиторская задолженность?", "backHtml": "\n\nДолги фирмы перед другими лицами за уже полученные, но ещё не оплаченные товары, работы или услуги."}, {"id": 1777129948361, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Через сколько лет списывается КЗ?", "a": ["Через 3 года (срок исковой давности) или при ликвидации кредитора."], "frontHtml": "Через сколько лет списывается КЗ?", "backHtml": "\n\nЧерез 3 года (срок исковой давности) или при ликвидации кредитора."}, {"id": 1777129948362, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Куда относится списанная КЗ?", "a": ["В прочие доходы фирмы."], "frontHtml": "Куда относится списанная КЗ?", "backHtml": "\n\nВ прочие доходы фирмы."}, {"id": 1777129948363, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Два вида активов по сроку использования", "a": ["Внеоборотные (> 1 года) и оборотные (≤ 1 года или постоянно в обороте)."], "frontHtml": "Два вида активов по сроку использования", "backHtml": "\n\nВнеоборотные (&gt; 1 года) и оборотные (≤ 1 года или постоянно в обороте)."}, {"id": 1777129948364, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Примеры внеоборотных активов", "a": ["НМА, основные средства, незавершённое строительство, долгосрочные финансовые вложения."], "frontHtml": "Примеры внеоборотных активов", "backHtml": "\n\nНМА, основные средства, незавершённое строительство, долгосрочные финансовые вложения."}, {"id": 1777129948365, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Примеры оборотных активов", "a": ["Запасы, ДЗ, краткосрочные финансовые вложения, денежные средства, расходы будущих периодов."], "frontHtml": "Примеры оборотных активов", "backHtml": "\n\nЗапасы, ДЗ, краткосрочные финансовые вложения, денежные средства, расходы будущих периодов."}, {"id": 1777129948366, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "По какой стоимости активы отражаются в балансе?", "a": ["По первоначальной (исторической) стоимости — стоимости приобретения или создания."], "frontHtml": "По какой стоимости активы отражаются в балансе?", "backHtml": "\n\nПо первоначальной (исторической) стоимости — стоимости приобретения или создания."}, {"id": 1777129948367, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НМА — расшифровка и определение", "a": ["Нематериальные активы — активы без материальной формы, используемые > 12 месяцев и приносящие экономическую выгоду."], "frontHtml": "НМА — расшифровка и определение", "backHtml": "\n\nНематериальные активы — активы без материальной формы, используемые &gt; 12 месяцев и приносящие экономическую выгоду."}, {"id": 1777129948368, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Нормативный документ по учёту НМА", "a": ["ПБУ 14/2007."], "frontHtml": "Нормативный документ по учёту НМА", "backHtml": "\n\nПБУ 14/2007."}, {"id": 1777129948369, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Шесть условий признания актива нематериальным", "a": ["1. Нет материальной формы. 2. Отделим. 3. Используется в производстве/управлении. 4. Срок > 12 мес. 5. Не для перепродажи. 6. Подтверждён документами."], "frontHtml": "Шесть условий признания актива нематериальным", "backHtml": "\n\n1. Нет материальной формы. 2. Отделим. 3. Используется в производстве/управлении. 4. Срок &gt; 12 мес. 5. Не для перепродажи. 6. Подтверждён документами."}, {"id": 1777129948370, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое деловая репутация (гудвилл)?", "a": ["Разница между ценой покупки бизнеса как имущественного комплекса и стоимостью его чистых активов (активы минус обязательства)."], "frontHtml": "Что такое деловая репутация (гудвилл)?", "backHtml": "\n\nРазница между ценой покупки бизнеса как имущественного комплекса и стоимостью его чистых активов (активы минус обязательства)."}, {"id": 1777129948371, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как амортизируется деловая репутация?", "a": ["Только линейным методом в течение 20 лет."], "frontHtml": "Как амортизируется деловая репутация?", "backHtml": "\n\nТолько линейным методом в течение 20 лет."}, {"id": 1777129948372, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "По какой стоимости НМА отражаются в балансе?", "a": ["По остаточной стоимости = первоначальная стоимость − накопленная амортизация."], "frontHtml": "По какой стоимости НМА отражаются в балансе?", "backHtml": "\n\nПо остаточной стоимости = первоначальная стоимость − накопленная амортизация."}, {"id": 1777129948373, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Первоначальная стоимость НМА при покупке включает", "a": ["Цена продавца (без НДС), невозмещаемые налоги, расходы на доработку, пошлины, услуги нотариуса и консультантов."], "frontHtml": "Первоначальная стоимость НМА при покупке включает", "backHtml": "\n\nЦена продавца (без НДС), невозмещаемые налоги, расходы на доработку, пошлины, услуги нотариуса и консультантов."}, {"id": 1777129948374, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как оценивается НМА, внесённый в УК?", "a": ["По стоимости, согласованной между акционерами."], "frontHtml": "Как оценивается НМА, внесённый в УК?", "backHtml": "\n\nПо стоимости, согласованной между акционерами."}, {"id": 1777129948375, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как оценивается НМА, полученный безвозмездно?", "a": ["По рыночной стоимости на дату получения."], "frontHtml": "Как оценивается НМА, полученный безвозмездно?", "backHtml": "\n\nПо рыночной стоимости на дату получения."}, {"id": 1777129948376, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое НИР?", "a": ["Научно-исследовательские работы."], "frontHtml": "Что такое НИР?", "backHtml": "\n\nНаучно-исследовательские работы."}, {"id": 1777129948377, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое НИОКР?", "a": ["Научно-исследовательские и опытно-конструкторские работы."], "frontHtml": "Что такое НИОКР?", "backHtml": "\n\nНаучно-исследовательские и опытно-конструкторские работы."}, {"id": 1777129948378, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Когда расходы на НИОКР попадают в отдельную строку баланса?", "a": ["Если исследования завершены и их результаты будут приносить экономическую выгоду в будущем."], "frontHtml": "Когда расходы на НИОКР попадают в отдельную строку баланса?", "backHtml": "\n\nЕсли исследования завершены и их результаты будут приносить экономическую выгоду в будущем."}, {"id": 1777129948379, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ОС — расшифровка и определение", "a": ["Основные средства — материальное имущество, используемое в производстве или управлении более 1 года."], "frontHtml": "ОС — расшифровка и определение", "backHtml": "\n\nОсновные средства — материальное имущество, используемое в производстве или управлении более 1 года."}, {"id": 1777129948380, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Нормативный документ по учёту ОС", "a": ["ПБУ 6/01 «Учёт основных средств»."], "frontHtml": "Нормативный документ по учёту ОС", "backHtml": "\n\nПБУ 6/01 «Учёт основных средств»."}, {"id": 1777129948381, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Четыре условия признания актива основным средством", "a": ["1. Для производства/управления. 2. Срок > 12 мес. 3. Не для перепродажи. 4. Будет приносить доход."], "frontHtml": "Четыре условия признания актива основным средством", "backHtml": "\n\n1. Для производства/управления. 2. Срок &gt; 12 мес. 3. Не для перепродажи. 4. Будет приносить доход."}, {"id": 1777129948382, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое инвентарный объект?", "a": ["Единица учёта ОС — отдельный предмет или комплекс предметов с единым управлением на общем фундаменте."], "frontHtml": "Что такое инвентарный объект?", "backHtml": "\n\nЕдиница учёта ОС — отдельный предмет или комплекс предметов с единым управлением на общем фундаменте."}, {"id": 1777129948383, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "По какой стоимости ОС отражаются в балансе?", "a": ["По остаточной стоимости = первоначальная стоимость − накопленная амортизация."], "frontHtml": "По какой стоимости ОС отражаются в балансе?", "backHtml": "\n\nПо остаточной стоимости = первоначальная стоимость − накопленная амортизация."}, {"id": 1777129948384, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "При каком условии ОС < 40 000 руб. можно не ставить на учёт как ОС?", "a": ["Такие объекты разрешено учитывать как запасы и списывать в расходы при вводе в эксплуатацию."], "frontHtml": "При каком условии ОС &lt; 40 000 руб. можно не ставить на учёт как ОС?", "backHtml": "\n\nТакие объекты разрешено учитывать как запасы и списывать в расходы при вводе в эксплуатацию."}, {"id": 1777129948385, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Когда можно изменить первоначальную стоимость ОС?", "a": ["При достройке, дооборудовании, реконструкции/модернизации, частичной ликвидации или переоценке."], "frontHtml": "Когда можно изменить первоначальную стоимость ОС?", "backHtml": "\n\nПри достройке, дооборудовании, реконструкции/модернизации, частичной ликвидации или переоценке."}, {"id": 1777129948386, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Влияет ли ремонт на стоимость ОС?", "a": ["Нет. Ремонт — текущий расход. Стоимость ОС не изменяет."], "frontHtml": "Влияет ли ремонт на стоимость ОС?", "backHtml": "\n\nНет. Ремонт — текущий расход. Стоимость ОС не изменяет."}, {"id": 1777129948387, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как часто можно проводить переоценку ОС?", "a": ["Не чаще одного раза в год (на конец года), по однородным группам ОС."], "frontHtml": "Как часто можно проводить переоценку ОС?", "backHtml": "\n\nНе чаще одного раза в год (на конец года), по однородным группам ОС."}, {"id": 1777129948388, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что происходит при дооценке ОС?", "a": ["Стоимость ОС растёт, увеличивается добавочный капитал в пассиве баланса."], "frontHtml": "Что происходит при дооценке ОС?", "backHtml": "\n\nСтоимость ОС растёт, увеличивается добавочный капитал в пассиве баланса."}, {"id": 1777129948389, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что происходит при уценке ОС?", "a": ["Стоимость ОС снижается, разница относится на прочие расходы (или уменьшает ранее сделанную дооценку)."], "frontHtml": "Что происходит при уценке ОС?", "backHtml": "\n\nСтоимость ОС снижается, разница относится на прочие расходы (или уменьшает ранее сделанную дооценку)."}, {"id": 1777129948390, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое амортизация?", "a": ["Постепенное перенесение стоимости ОС или НМА на затраты в течение срока полезного использования."], "frontHtml": "Что такое амортизация?", "backHtml": "\n\nПостепенное перенесение стоимости ОС или НМА на затраты в течение срока полезного использования."}, {"id": 1777129948391, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Формула линейного метода амортизации", "a": ["Годовая амортизация = Первоначальная стоимость ÷ Срок полезного использования (лет)."], "frontHtml": "Формула линейного метода амортизации", "backHtml": "\n\nГодовая амортизация = Первоначальная стоимость ÷ Срок полезного использования (лет)."}, {"id": 1777129948392, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Какие ОС не амортизируются?", "a": ["Земля, природные ресурсы, объекты на консервации > 3 мес., объекты на реконструкции > 12 мес."], "frontHtml": "Какие ОС не амортизируются?", "backHtml": "\n\nЗемля, природные ресурсы, объекты на консервации &gt; 3 мес., объекты на реконструкции &gt; 12 мес."}, {"id": 1777129948393, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Четыре метода начисления амортизации ОС", "a": ["1. Линейный. 2. Уменьшаемого остатка. 3. По сумме чисел лет. 4. Пропорционально объёму продукции."], "frontHtml": "Четыре метода начисления амортизации ОС", "backHtml": "\n\n1. Линейный. 2. Уменьшаемого остатка. 3. По сумме чисел лет. 4. Пропорционально объёму продукции."}, {"id": 1777129948394, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое незавершённое строительство?", "a": ["Затраты на ОС, ещё не введённые в эксплуатацию. После ввода переходят в состав ОС и начинается амортизация."], "frontHtml": "Что такое незавершённое строительство?", "backHtml": "\n\nЗатраты на ОС, ещё не введённые в эксплуатацию. После ввода переходят в состав ОС и начинается амортизация."}, {"id": 1777129948395, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три метода списания запасов в производство", "a": ["ФИФО, по средней себестоимости, по себестоимости каждой единицы."], "frontHtml": "Три метода списания запасов в производство", "backHtml": "\n\nФИФО, по средней себестоимости, по себестоимости каждой единицы."}, {"id": 1777129948396, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что означает метод ФИФО?", "a": ["Первым в производство уходит материал из самой ранней партии. Остаток оценивается по ценам последних поступлений."], "frontHtml": "Что означает метод ФИФО?", "backHtml": "\n\nПервым в производство уходит материал из самой ранней партии. Остаток оценивается по ценам последних поступлений."}, {"id": 1777129948397, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Запрещён ли метод ЛИФО в бухучёте?", "a": ["Да, с 1 января 2008 г. ЛИФО запрещён в бухгалтерском учёте. В налоговом — разрешён."], "frontHtml": "Запрещён ли метод ЛИФО в бухучёте?", "backHtml": "\n\nДа, с 1 января 2008 г. ЛИФО запрещён в бухгалтерском учёте. В налоговом — разрешён."}, {"id": 1777129948398, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое резерв под снижение стоимости материальных ценностей?", "a": ["Резерв, создаваемый когда рыночная цена запасов упала ниже фактической себестоимости. В балансе запасы отражаются за вычетом резерва."], "frontHtml": "Что такое резерв под снижение стоимости материальных ценностей?", "backHtml": "\n\nРезерв, создаваемый когда рыночная цена запасов упала ниже фактической себестоимости. В балансе запасы отражаются за вычетом резерва."}, {"id": 1777129948399, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Формула себестоимости готовой продукции", "a": ["НП на начало + Затраты за период − Брак − НП на конец."], "frontHtml": "Формула себестоимости готовой продукции", "backHtml": "\n\nНП на начало + Затраты за период − Брак − НП на конец."}, {"id": 1777129948400, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое товары отгруженные?", "a": ["Товары, переданные покупателю физически, но право собственности ещё не перешло (по условиям договора). Числятся на балансе продавца."], "frontHtml": "Что такое товары отгруженные?", "backHtml": "\n\nТовары, переданные покупателю физически, но право собственности ещё не перешло (по условиям договора). Числятся на балансе продавца."}, {"id": 1777129948401, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое входящий НДС?", "a": ["НДС, уплаченный поставщикам при покупке товаров, работ, услуг. Отражается в активе баланса до принятия к вычету."], "frontHtml": "Что такое входящий НДС?", "backHtml": "\n\nНДС, уплаченный поставщикам при покупке товаров, работ, услуг. Отражается в активе баланса до принятия к вычету."}, {"id": 1777129948402, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое исходящий НДС?", "a": ["НДС, начисленный с выручки. Отражается в пассиве как КЗ перед бюджетом."], "frontHtml": "Что такое исходящий НДС?", "backHtml": "\n\nНДС, начисленный с выручки. Отражается в пассиве как КЗ перед бюджетом."}, {"id": 1777129948403, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Сколько НДС платится в бюджет?", "a": ["Разница: исходящий НДС − входящий НДС."], "frontHtml": "Сколько НДС платится в бюджет?", "backHtml": "\n\nРазница: исходящий НДС − входящий НДС."}, {"id": 1777129948404, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три условия для вычета входящего НДС", "a": ["1. Покупка для облагаемой НДС деятельности. 2. Есть счёт-фактура. 3. В документах НДС выделен отдельной строкой."], "frontHtml": "Три условия для вычета входящего НДС", "backHtml": "\n\n1. Покупка для облагаемой НДС деятельности. 2. Есть счёт-фактура. 3. В документах НДС выделен отдельной строкой."}, {"id": 1777129948405, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое дебиторская задолженность?", "a": ["Долги перед фирмой: от покупателей, авансы выданные поставщикам, переплата налогов."], "frontHtml": "Что такое дебиторская задолженность?", "backHtml": "\n\nДолги перед фирмой: от покупателей, авансы выданные поставщикам, переплата налогов."}, {"id": 1777129948406, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое сомнительный долг?", "a": ["ДЗ, не погашенная в срок по договору и не обеспеченная гарантиями."], "frontHtml": "Что такое сомнительный долг?", "backHtml": "\n\nДЗ, не погашенная в срок по договору и не обеспеченная гарантиями."}, {"id": 1777129948407, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Обязателен ли резерв сомнительных долгов?", "a": ["Да, с 2011 г. его создание обязательно. В балансе ДЗ отражается за вычетом резерва."], "frontHtml": "Обязателен ли резерв сомнительных долгов?", "backHtml": "\n\nДа, с 2011 г. его создание обязательно. В балансе ДЗ отражается за вычетом резерва."}, {"id": 1777129948408, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое расходы будущих периодов?", "a": ["Предоплаченные затраты, относящиеся к будущим периодам (лицензии, разрешения, сертификация). Списываются равномерно."], "frontHtml": "Что такое расходы будущих периодов?", "backHtml": "\n\nПредоплаченные затраты, относящиеся к будущим периодам (лицензии, разрешения, сертификация). Списываются равномерно."}, {"id": 1777129948409, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Являются ли авансы поставщикам расходами будущих периодов?", "a": ["Нет. Авансы поставщикам — это дебиторская задолженность."], "frontHtml": "Являются ли авансы поставщикам расходами будущих периодов?", "backHtml": "\n\nНет. Авансы поставщикам — это дебиторская задолженность."}, {"id": 1777129948410, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое доходы будущих периодов (ДБП)?", "a": ["Деньги, полученные за услуги будущих периодов (абонементы, годовые карты). Отражаются в пассиве и списываются по мере оказания услуг."], "frontHtml": "Что такое доходы будущих периодов (ДБП)?", "backHtml": "\n\nДеньги, полученные за услуги будущих периодов (абонементы, годовые карты). Отражаются в пассиве и списываются по мере оказания услуг."}, {"id": 1777129948411, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Являются ли авансы от покупателей доходами будущих периодов?", "a": ["Нет. Авансы от покупателей — это кредиторская задолженность."], "frontHtml": "Являются ли авансы от покупателей доходами будущих периодов?", "backHtml": "\n\nНет. Авансы от покупателей — это кредиторская задолженность."}, {"id": 1777129948412, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как учитываются безвозмездно полученные ценности?", "a": ["Как доходы будущих периодов по рыночной стоимости. Списываются по мере начисления амортизации (для ОС) или передачи в производство (для материалов)."], "frontHtml": "Как учитываются безвозмездно полученные ценности?", "backHtml": "\n\nКак доходы будущих периодов по рыночной стоимости. Списываются по мере начисления амортизации (для ОС) или передачи в производство (для материалов)."}, {"id": 1777129948413, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое резервы предстоящих расходов?", "a": ["Резервы для равномерного включения крупных предсказуемых расходов в себестоимость (отпуска, гарантийный ремонт)."], "frontHtml": "Что такое резервы предстоящих расходов?", "backHtml": "\n\nРезервы для равномерного включения крупных предсказуемых расходов в себестоимость (отпуска, гарантийный ремонт)."}, {"id": 1777129948414, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое долгосрочные и краткосрочные обязательства?", "a": ["Долгосрочные — срок погашения более 1 года. Краткосрочные — срок погашения 1 год и менее."], "frontHtml": "Что такое долгосрочные и краткосрочные обязательства?", "backHtml": "\n\nДолгосрочные — срок погашения более 1 года. Краткосрочные — срок погашения 1 год и менее."}, {"id": 1777129948415, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое облигационный заём?", "a": ["Деньги, привлечённые путём выпуска и продажи облигаций. Учитывается как заёмные средства."], "frontHtml": "Что такое облигационный заём?", "backHtml": "\n\nДеньги, привлечённые путём выпуска и продажи облигаций. Учитывается как заёмные средства."}, {"id": 1777129948416, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое выручка в бухучёте?", "a": ["Доходы от основной деятельности (доля > 5% от общей выручки), без НДС и акцизов."], "frontHtml": "Что такое выручка в бухучёте?", "backHtml": "\n\nДоходы от основной деятельности (доля &gt; 5% от общей выручки), без НДС и акцизов."}, {"id": 1777129948417, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Два метода учёта выручки", "a": ["Метод начисления (акруальный) и кассовый метод."], "frontHtml": "Два метода учёта выручки", "backHtml": "\n\nМетод начисления (акруальный) и кассовый метод."}, {"id": 1777129948418, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "В чём суть метода начисления?", "a": ["Выручка признаётся в момент перехода права собственности на товары или подписания акта приёмки, независимо от оплаты."], "frontHtml": "В чём суть метода начисления?", "backHtml": "\n\nВыручка признаётся в момент перехода права собственности на товары или подписания акта приёмки, независимо от оплаты."}, {"id": 1777129948419, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "В чём суть кассового метода?", "a": ["Выручка признаётся при фактическом получении денег от покупателя."], "frontHtml": "В чём суть кассового метода?", "backHtml": "\n\nВыручка признаётся при фактическом получении денег от покупателя."}, {"id": 1777129948420, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Кому разрешён кассовый метод учёта?", "a": ["Только малым предприятиям. Крупные организации обязаны применять метод начисления."], "frontHtml": "Кому разрешён кассовый метод учёта?", "backHtml": "\n\nТолько малым предприятиям. Крупные организации обязаны применять метод начисления."}, {"id": 1777129948421, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Обязательно ли совпадение методов учёта доходов и расходов?", "a": ["Да. Метод учёта доходов и расходов должен быть одинаковым в рамках одной организации."], "frontHtml": "Обязательно ли совпадение методов учёта доходов и расходов?", "backHtml": "\n\nДа. Метод учёта доходов и расходов должен быть одинаковым в рамках одной организации."}, {"id": 1777129948422, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое себестоимость продаж в ОПУ?", "a": ["Прямые производственные затраты, связанные с реализованной продукцией (материалы, зарплата рабочих, амортизация производственных ОС)."], "frontHtml": "Что такое себестоимость продаж в ОПУ?", "backHtml": "\n\nПрямые производственные затраты, связанные с реализованной продукцией (материалы, зарплата рабочих, амортизация производственных ОС)."}, {"id": 1777129948423, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое валовая прибыль?", "a": ["Выручка − Себестоимость продаж."], "frontHtml": "Что такое валовая прибыль?", "backHtml": "\n\nВыручка − Себестоимость продаж."}, {"id": 1777129948424, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое коммерческие расходы?", "a": ["Затраты на сбыт продукции: реклама, транспортировка до покупателя, упаковка, зарплата продавцов."], "frontHtml": "Что такое коммерческие расходы?", "backHtml": "\n\nЗатраты на сбыт продукции: реклама, транспортировка до покупателя, упаковка, зарплата продавцов."}, {"id": 1777129948425, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое управленческие расходы?", "a": ["Общехозяйственные расходы: зарплата администрации, аренда офиса, расходы на бухгалтерию."], "frontHtml": "Что такое управленческие расходы?", "backHtml": "\n\nОбщехозяйственные расходы: зарплата администрации, аренда офиса, расходы на бухгалтерию."}, {"id": 1777129948426, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое прибыль от продаж?", "a": ["Валовая прибыль − Коммерческие расходы − Управленческие расходы."], "frontHtml": "Что такое прибыль от продаж?", "backHtml": "\n\nВаловая прибыль − Коммерческие расходы − Управленческие расходы."}, {"id": 1777129948427, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Нормативный документ по составу расходов организации", "a": ["ПБУ 10/99 «Расходы организации»."], "frontHtml": "Нормативный документ по составу расходов организации", "backHtml": "\n\nПБУ 10/99 «Расходы организации»."}, {"id": 1777129948428, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Пять групп расходов по ПБУ 10/99", "a": ["Материальные расходы, оплата труда, отчисления на соц. нужды, амортизация, прочие расходы."], "frontHtml": "Пять групп расходов по ПБУ 10/99", "backHtml": "\n\nМатериальные расходы, оплата труда, отчисления на соц. нужды, амортизация, прочие расходы."}, {"id": 1777129948429, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Чем метод полной себестоимости отличается от директ-костинга?", "a": ["Полная себестоимость: все расходы (прямые + косвенные) включаются в себестоимость. Директ-костинг: только прямые"], "frontHtml": "Чем метод полной себестоимости отличается от директ-костинга?", "backHtml": "\n\nПолная себестоимость: все расходы (прямые + косвенные) включаются в себестоимость. Директ-костинг: только прямые"}, {"id": 1777129948430, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое прочие доходы в ОПУ?", "a": ["Доходы, не относящиеся к основной деятельности: дивиденды полученные, аренда (не основная), прибыль от продажи ОС, списанная КЗ, безвозмездное имущество."], "frontHtml": "Что такое прочие доходы в ОПУ?", "backHtml": "\n\nДоходы, не относящиеся к основной деятельности: дивиденды полученные, аренда (не основная), прибыль от продажи ОС, списанная КЗ, безвозмездное имущество."}, {"id": 1777129948431, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое прочие расходы в ОПУ?", "a": ["Расходы, не относящиеся к основной деятельности: проценты к уплате, резервы, штрафы, убыток от продажи ОС, безнадёжные долги."], "frontHtml": "Что такое прочие расходы в ОПУ?", "backHtml": "\n\nРасходы, не относящиеся к основной деятельности: проценты к уплате, резервы, штрафы, убыток от продажи ОС, безнадёжные долги."}, {"id": 1777129948432, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Когда проценты по займу включаются в стоимость актива?", "a": ["Если заём привлечён для приобретения инвестиционного актива (ОС, строительство) — до ввода в эксплуатацию. После ввода — в прочие расходы."], "frontHtml": "Когда проценты по займу включаются в стоимость актива?", "backHtml": "\n\nЕсли заём привлечён для приобретения инвестиционного актива (ОС, строительство) — до ввода в эксплуатацию. После ввода — в прочие расходы."}, {"id": 1777129948433, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое положительная курсовая разница?", "a": ["Прочий доход, возникающий при пересчёте валютных активов/обязательств, когда рубль ослаб (валютный актив вырос в рублях)."], "frontHtml": "Что такое положительная курсовая разница?", "backHtml": "\n\nПрочий доход, возникающий при пересчёте валютных активов/обязательств, когда рубль ослаб (валютный актив вырос в рублях)."}, {"id": 1777129948434, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое отрицательная курсовая разница?", "a": ["Прочий расход, возникающий при пересчёте, когда рубль укрепился (валютный актив упал в рублях) или валютный долг вырос."], "frontHtml": "Что такое отрицательная курсовая разница?", "backHtml": "\n\nПрочий расход, возникающий при пересчёте, когда рубль укрепился (валютный актив упал в рублях) или валютный долг вырос."}, {"id": 1777129948435, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое условный расход по налогу на прибыль?", "a": ["Бухгалтерская прибыль × ставка налога. Теоретический налог исходя из данных бухучёта."], "frontHtml": "Что такое условный расход по налогу на прибыль?", "backHtml": "\n\nБухгалтерская прибыль × ставка налога. Теоретический налог исходя из данных бухучёта."}, {"id": 1777129948436, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое текущий (фактический) налог на прибыль?", "a": ["Фактическая сумма налога к уплате, рассчитанная по данным налогового учёта по главе 25 НК РФ."], "frontHtml": "Что такое текущий (фактический) налог на прибыль?", "backHtml": "\n\nФактическая сумма налога к уплате, рассчитанная по данным налогового учёта по главе 25 НК РФ."}, {"id": 1777129948437, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое ПНО?", "a": ["Постоянное налоговое обязательство — возникает, когда расход принят в бухучёте, но никогда не будет принят в налоговом учёте (напр., благотворительность). Увеличивает налог."], "frontHtml": "Что такое ПНО?", "backHtml": "\n\nПостоянное налоговое обязательство — возникает, когда расход принят в бухучёте, но никогда не будет принят в налоговом учёте (напр., благотворительность). Увеличивает налог."}, {"id": 1777129948438, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое ПНА?", "a": ["Постоянный налоговый актив — расход принят в налоговом учёте, но не в бухгалтерском. Уменьшает налог."], "frontHtml": "Что такое ПНА?", "backHtml": "\n\nПостоянный налоговый актив — расход принят в налоговом учёте, но не в бухгалтерском. Уменьшает налог."}, {"id": 1777129948439, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое ОНО?", "a": ["Отложенное налоговое обязательство — временная разница: сейчас платим налог меньше, в будущем заплатим больше. Отражается в пассиве баланса."], "frontHtml": "Что такое ОНО?", "backHtml": "\n\nОтложенное налоговое обязательство — временная разница: сейчас платим налог меньше, в будущем заплатим больше. Отражается в пассиве баланса."}, {"id": 1777129948440, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое ОНА?", "a": ["Отложенный налоговый актив — временная разница: сейчас платим налог больше, в будущем заплатим меньше. Отражается в активе баланса."], "frontHtml": "Что такое ОНА?", "backHtml": "\n\nОтложенный налоговый актив — временная разница: сейчас платим налог больше, в будущем заплатим меньше. Отражается в активе баланса."}, {"id": 1777129948441, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Нормативный документ по учёту налога на прибыль в бухучёте", "a": ["ПБУ 18/02 «Учёт расходов по налогу на прибыль»."], "frontHtml": "Нормативный документ по учёту налога на прибыль в бухучёте", "backHtml": "\n\nПБУ 18/02 «Учёт расходов по налогу на прибыль»."}, {"id": 1777129948442, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Формула чистой прибыли", "a": ["Прибыль до налогообложения − Текущий налог ± Изменение ОНО ± Изменение ОНА."], "frontHtml": "Формула чистой прибыли", "backHtml": "\n\nПрибыль до налогообложения − Текущий налог ± Изменение ОНО ± Изменение ОНА."}, {"id": 1777129948443, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Зачем нужен ОДДС?", "a": ["Чтобы оценить реальное движение денег. Прибыльная фирма может иметь нехватку денег и наоборот."], "frontHtml": "Зачем нужен ОДДС?", "backHtml": "\n\nЧтобы оценить реальное движение денег. Прибыльная фирма может иметь нехватку денег и наоборот."}, {"id": 1777129948444, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Три раздела ОДДС", "a": ["Текущая (операционная), инвестиционная и финансовая деятельность."], "frontHtml": "Три раздела ОДДС", "backHtml": "\n\nТекущая (операционная), инвестиционная и финансовая деятельность."}, {"id": 1777129948445, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что входит в текущую деятельность ОДДС?", "a": ["Поступления от продаж и прочие операционные"], "frontHtml": "Что входит в текущую деятельность ОДДС?", "backHtml": "\n\nПоступления от продаж и прочие операционные"}, {"id": 1777129948446, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что входит в инвестиционную деятельность ОДДС?", "a": ["Покупка/продажа ОС и НМА, финансовые вложения, выдача/возврат займов, дивиденды полученные."], "frontHtml": "Что входит в инвестиционную деятельность ОДДС?", "backHtml": "\n\nПокупка/продажа ОС и НМА, финансовые вложения, выдача/возврат займов, дивиденды полученные."}, {"id": 1777129948447, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что входит в финансовую деятельность ОДДС?", "a": ["Получение и погашение кредитов, выпуск акций, выплата дивидендов, выкуп собственных акций."], "frontHtml": "Что входит в финансовую деятельность ОДДС?", "backHtml": "\n\nПолучение и погашение кредитов, выпуск акций, выплата дивидендов, выкуп собственных акций."}, {"id": 1777129948448, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как в ОДДС отражается выручка — с НДС или без?", "a": ["В ОДДС — с НДС (в отличие от ОПУ, где без НДС)."], "frontHtml": "Как в ОДДС отражается выручка — с НДС или без?", "backHtml": "\n\nВ ОДДС — с НДС (в отличие от ОПУ, где без НДС)."}, {"id": 1777129948449, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Чему равен конечный остаток ОДДС?", "a": ["Строке «Денежные средства» в бухгалтерском балансе на ту же дату."], "frontHtml": "Чему равен конечный остаток ОДДС?", "backHtml": "\n\nСтроке «Денежные средства» в бухгалтерском балансе на ту же дату."}, {"id": 1777129948450, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое пояснительная записка?", "a": ["Обязательная часть бухгалтерской отчётности с дополнительными сведениями о финансовом положении фирмы, не вошедшими в основные формы."], "frontHtml": "Что такое пояснительная записка?", "backHtml": "\n\nОбязательная часть бухгалтерской отчётности с дополнительными сведениями о финансовом положении фирмы, не вошедшими в основные формы."}, {"id": 1777129948451, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Кто может не составлять пояснительную записку?", "a": ["Малые предприятия."], "frontHtml": "Кто может не составлять пояснительную записку?", "backHtml": "\n\nМалые предприятия."}, {"id": 1777129948452, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что детализируют приложения к балансу?", "a": ["НМА, ОС, незавершённое строительство, НИОКР, финансовые вложения, ДЗ и КЗ. Показывается движение за год."], "frontHtml": "Что детализируют приложения к балансу?", "backHtml": "\n\nНМА, ОС, незавершённое строительство, НИОКР, финансовые вложения, ДЗ и КЗ. Показывается движение за год."}, {"id": 1777129948453, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Что такое события после отчётной даты?", "a": ["Обстоятельства, возникшие после 31 декабря, но до подписания отчётности. Регулируются ПБУ 7/98."], "frontHtml": "Что такое события после отчётной даты?", "backHtml": "\n\nОбстоятельства, возникшие после 31 декабря, но до подписания отчётности. Регулируются ПБУ 7/98."}, {"id": 1777129948454, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Два вида событий после отчётной даты", "a": ["Подтверждающие (уточняют факты, существовавшие на 31.12) и неподтверждающие (новые факты, возникшие после 31.12)."], "frontHtml": "Два вида событий после отчётной даты", "backHtml": "\n\nПодтверждающие (уточняют факты, существовавшие на 31.12) и неподтверждающие (новые факты, возникшие после 31.12)."}, {"id": 1777129948455, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как отражаются подтверждающие события после отчётной даты?", "a": ["Корректируются показатели самой отчётности."], "frontHtml": "Как отражаются подтверждающие события после отчётной даты?", "backHtml": "\n\nКорректируются показатели самой отчётности."}, {"id": 1777129948456, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "Как отражаются неподтверждающие события после отчётной даты?", "a": ["Не корректируют отчётность, но раскрываются в пояснительной записке."], "frontHtml": "Как отражаются неподтверждающие события после отчётной даты?", "backHtml": "\n\nНе корректируют отчётность, но раскрываются в пояснительной записке."}, {"id": 1777129948457, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НДС — расшифровка", "a": ["Налог на добавленную стоимость."], "frontHtml": "НДС — расшифровка", "backHtml": "\n\nНалог на добавленную стоимость."}, {"id": 1777129948458, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НК РФ — расшифровка", "a": ["Налоговый кодекс Российской Федерации."], "frontHtml": "НК РФ — расшифровка", "backHtml": "\n\nНалоговый кодекс Российской Федерации."}, {"id": 1777129948459, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НИОКР — расшифровка", "a": ["Научно-исследовательские и опытно-конструкторские работы."], "frontHtml": "НИОКР — расшифровка", "backHtml": "\n\nНаучно-исследовательские и опытно-конструкторские работы."}, {"id": 1777129948460, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НИР — расшифровка", "a": ["Научно-исследовательские работы."], "frontHtml": "НИР — расшифровка", "backHtml": "\n\nНаучно-исследовательские работы."}, {"id": 1777129948461, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ОПУ — расшифровка", "a": ["Отчёт о прибылях и убытках."], "frontHtml": "ОПУ — расшифровка", "backHtml": "\n\nОтчёт о прибылях и убытках."}, {"id": 1777129948462, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ОДДС — расшифровка", "a": ["Отчёт о движении денежных средств."], "frontHtml": "ОДДС — расшифровка", "backHtml": "\n\nОтчёт о движении денежных средств."}, {"id": 1777129948463, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "УК — расшифровка", "a": ["Уставный капитал."], "frontHtml": "УК — расшифровка", "backHtml": "\n\nУставный капитал."}, {"id": 1777129948464, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "КЗ — расшифровка", "a": ["Кредиторская задолженность."], "frontHtml": "КЗ — расшифровка", "backHtml": "\n\nКредиторская задолженность."}, {"id": 1777129948465, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ДЗ — расшифровка", "a": ["Дебиторская задолженность."], "frontHtml": "ДЗ — расшифровка", "backHtml": "\n\nДебиторская задолженность."}, {"id": 1777129948466, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ДБП — расшифровка", "a": ["Доходы будущих периодов."], "frontHtml": "ДБП — расшифровка", "backHtml": "\n\nДоходы будущих периодов."}, {"id": 1777129948467, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НП — расшифровка", "a": ["Незавершённое производство."], "frontHtml": "НП — расшифровка", "backHtml": "\n\nНезавершённое производство."}, {"id": 1777129948468, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ОС — расшифровка", "a": ["Основные средства."], "frontHtml": "ОС — расшифровка", "backHtml": "\n\nОсновные средства."}, {"id": 1777129948469, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "НМА — расшифровка", "a": ["Нематериальные активы."], "frontHtml": "НМА — расшифровка", "backHtml": "\n\nНематериальные активы."}, {"id": 1777129948470, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПНО — расшифровка", "a": ["Постоянное налоговое обязательство."], "frontHtml": "ПНО — расшифровка", "backHtml": "\n\nПостоянное налоговое обязательство."}, {"id": 1777129948471, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПНА — расшифровка", "a": ["Постоянный налоговый актив."], "frontHtml": "ПНА — расшифровка", "backHtml": "\n\nПостоянный налоговый актив."}, {"id": 1777129948472, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ОНО — расшифровка", "a": ["Отложенное налоговое обязательство."], "frontHtml": "ОНО — расшифровка", "backHtml": "\n\nОтложенное налоговое обязательство."}, {"id": 1777129948473, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ОНА — расшифровка", "a": ["Отложенный налоговый актив."], "frontHtml": "ОНА — расшифровка", "backHtml": "\n\nОтложенный налоговый актив."}, {"id": 1777129948474, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПФР — расшифровка", "a": ["Пенсионный фонд России."], "frontHtml": "ПФР — расшифровка", "backHtml": "\n\nПенсионный фонд России."}, {"id": 1777129948475, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ФСС — расшифровка", "a": ["Фонд социального страхования."], "frontHtml": "ФСС — расшифровка", "backHtml": "\n\nФонд социального страхования."}, {"id": 1777129948476, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ФОМС — расшифровка", "a": ["Фонд обязательного медицинского страхования."], "frontHtml": "ФОМС — расшифровка", "backHtml": "\n\nФонд обязательного медицинского страхования."}, {"id": 1777129948477, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ФНС — расшифровка", "a": ["Федеральная налоговая служба."], "frontHtml": "ФНС — расшифровка", "backHtml": "\n\nФедеральная налоговая служба."}, {"id": 1777129948478, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ФИФО — расшифровка", "a": ["First In First Out — первым пришёл, первым ушёл."], "frontHtml": "ФИФО — расшифровка", "backHtml": "\n\nFirst In First Out — первым пришёл, первым ушёл."}, {"id": 1777129948479, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПБУ 6/01 — что регулирует?", "a": ["Учёт основных средств."], "frontHtml": "ПБУ 6/01 — что регулирует?", "backHtml": "\n\nУчёт основных средств."}, {"id": 1777129948480, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПБУ 14/2007 — что регулирует?", "a": ["Учёт нематериальных активов."], "frontHtml": "ПБУ 14/2007 — что регулирует?", "backHtml": "\n\nУчёт нематериальных активов."}, {"id": 1777129948481, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПБУ 10/99 — что регулирует?", "a": ["Расходы организации: состав и признание."], "frontHtml": "ПБУ 10/99 — что регулирует?", "backHtml": "\n\nРасходы организации: состав и признание."}, {"id": 1777129948482, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПБУ 18/02 — что регулирует?", "a": ["Учёт расходов по налогу на прибыль (ОНО, ОНА, ПНО, ПНА)."], "frontHtml": "ПБУ 18/02 — что регулирует?", "backHtml": "\n\nУчёт расходов по налогу на прибыль (ОНО, ОНА, ПНО, ПНА)."}, {"id": 1777129948483, "topic": "aa0a0346419ff444", "sec": "Бух учет", "q": "ПБУ 7/98 — что регулирует?", "a": ["События после отчётной даты."], "frontHtml": "ПБУ 7/98 — что регулирует?", "backHtml": "\n\nСобытия после отчётной даты."}];